const prev = $('Compute Adaptive Distribution').first().json;
const content = $json.choices?.[0]?.message?.content || '';
let cleaned = content.trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error('Could not parse adaptive flashcards JSON from model response');
  }
}

const rawCards = Array.isArray(parsed?.flashcards) ? parsed.flashcards : (Array.isArray(parsed?.cards) ? parsed.cards : (Array.isArray(parsed) ? parsed : []));

const formattedFlashcards = rawCards.map((c, idx) => ({
  id: c.id || `c${idx + 1}`,
  difficulty: (c.difficulty || 'medium').toLowerCase(),
  front: c.front || c.question || c.term || `Concept ${idx + 1}`,
  back: c.back || c.answer || c.definition || 'Detailed explanation',
  key_takeaway: c.key_takeaway || c.takeaway || c.summary || 'Essential principle to remember.',
  subtopic: c.subtopic || c.category || prev.topic
}));

// Provide backward-compatible 'cards' array as well as the new 'flashcards' property
return [{
  json: {
    success: true,
    topic: parsed?.topic || prev.topic,
    score: typeof parsed?.score === 'number' ? parsed.score : prev.score,
    difficulty_distribution: parsed?.difficulty_distribution || prev.distribution,
    count: formattedFlashcards.length,
    flashcards: formattedFlashcards,
    cards: formattedFlashcards.map(f => ({ front: f.front, back: f.back }))
  }
}];
